questions.solution:
function stages(components) {
  const level = new Map();
  const byName = new Map(components.map((c) => [c.name, c]));
  const depth = (name) => {
    if (level.has(name)) return level.get(name);
    const deps = byName.get(name).dependsOn;
    const d = deps.length === 0 ? 0 : 1 + Math.max(...deps.map(depth));
    level.set(name, d);
    return d;
  };
  const result = [];
  for (const c of components) {
    const d = depth(c.name);
    (result[d] ??= []).push(c.name);
  }
  return result;
}

const shop = [
  { name: "http", dependsOn: ["queue", "cache"] },
  { name: "queue", dependsOn: ["database"] },
  { name: "database", dependsOn: [] },
  { name: "cache", dependsOn: [] },
];
for (const stage of stages(shop)) console.log(stage.join(", "));

