function retryDelays({ attempts, delay, maxDelay = 10000, backoff = "exponential" }) {
  const waits = [];
  for (let i = 0; i < attempts; i++) {
    const wait = backoff === "fixed" ? delay : delay * 2 ** i;
    waits.push(Math.min(wait, maxDelay));
  }
  return waits;
}

