function connect(ms, signal) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => resolve("connected"), ms);
    signal.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(signal.reason);
    }, { once: true });
  });
}

