async function stopWithDeadline(stops, ms) {
  const controller = new AbortController();
  let timer;
  const deadline = new Promise((resolve) => {
    timer = setTimeout(() => {
      controller.abort(new Error(`deadline of ${ms}ms`));
      resolve("deadline");
    }, ms);
  });
  const all = Promise.all(stops.map((stop) => stop(controller.signal))).then(() => "clean");
  const result = await Promise.race([all, deadline]);
  clearTimeout(timer);
  return result;
}

const worker = (signal) => new Promise((resolve) => {
  const t = setTimeout(resolve, 1000);
  signal.addEventListener("abort", () => { clearTimeout(t); console.log("worker aborted"); resolve(); });
});
const cache = async () => console.log("cache closed");
console.log(await stopWithDeadline([cache], 100));
console.log(await stopWithDeadline([cache, worker], 50));
